        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('11041111-0000-4000-8000-000000000001', 'If a set A has 4 elements, the number of elements in its Power Set P(A) is:', '{"A":"8","B":"16","C":"15","D":"4"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Sets', 1, 'n(P(A)) = 2⁴ = 16.', NULL, NULL, 'n(P(A)) = 2⁴ = 16.', 'EASY', true),
        ('11041111-0000-4000-8000-000000000002', 'For any two sets A and B, A ∪ (A ∩ B) equals:', '{"A":"B","B":"A","C":"A ∩ B","D":"∅"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Sets', 1, 'Absorption law: A ∩ B ⊆ A => union is A.', NULL, NULL, 'Absorption law: A ∩ B ⊆ A => union is A.', 'EASY', true),
        ('11041111-0000-4000-8000-000000000003', 'According to De Morgan''s law, (A ∪ B)'' equals:', '{"A":"A'' ∪ B''","B":"A'' ∩ B''","C":"A ∩ B","D":"(A ∩ B)''"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Sets', 1, '(A ∪ B)'' = A'' ∩ B''.', NULL, NULL, '(A ∪ B)'' = A'' ∩ B''.', 'EASY', true),
        ('11041111-0000-4000-8000-000000000004', 'Number of proper subsets of {1, 2, 3} is:', '{"A":"8","B":"7","C":"6","D":"3"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Sets', 1, '2³ - 1 = 7 proper subsets.', NULL, NULL, '2³ - 1 = 7 proper subsets.', 'EASY', true),
        ('11041111-0000-4000-8000-000000000005', 'If A = {x : x ∈ R, x² = 9 and 2x = 4}, then A is:', '{"A":"{3}","B":"{2}","C":"∅ (Empty set)","D":"{-3, 3}"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Sets', 1, 'x = ±3 contradicts x = 2 -> empty set.', NULL, NULL, 'x = ±3 contradicts x = 2 -> empty set.', 'EASY', true),
        ('11041111-0000-4000-8000-000000000006', 'Assertion (A): Every finite set has a countable finite number of subsets.
